package com.bank.csv.service;

import com.bank.csv.model.Employee;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class CsvImportService {
    private static final Logger log = Logger.getLogger(CsvImportService.class.getName());

    public List<Employee> parse(List<String> csvLines) {
        log.info(() -> "Parsing " + csvLines.size() + " CSV lines into Employee objects");
        return csvLines.stream()
                .map(line -> {
                    String[] parts = line.split(",");         // split at commas
                    String name = parts[0].trim();            // token 0: name
                    String dept = parts[1].trim();            // token 1: department
                    BigDecimal salary = new BigDecimal(parts[2].trim()); // token 2: money → BigDecimal
                    return new Employee(name, dept, salary);  // construct inside map
                })
                .collect(Collectors.toList());
    }
}
