package com.bank.csv;

import com.bank.csv.model.Employee;
import com.bank.csv.service.CsvImportService;
import java.util.List;
import java.util.logging.Logger;

public class Main {
    private static final Logger log = Logger.getLogger(Main.class.getName());

    public static void main(String[] args) {
        List<String> lines = List.of(
            "Rajesh,IT,95000",
            "Priya, Sales, 72000",   // stray spaces — trimmed away
            "Amit,HR,48000"
        );

        List<Employee> employees = new CsvImportService().parse(lines);
        employees.forEach(e -> log.info(() -> "Imported: " + e));
    }
}
